#include <stdlib.h>
    int *makeMatrix(int r, int c) {
        if (r <= 0 || c <= 0) return NULL;
        /* The question guarantees that this size fits size_t. */
        return malloc((size_t)r * (size_t)c * sizeof(int));
    }
    /* Access (i,j) as *(base + (size_t)i * c + j).
       Valid indices satisfy 0 <= i < r and 0 <= j < c.
       Caller checks the returned pointer and eventually frees it. */

Rows are adjacent in memory, so row i starts at offset $ic$ and column j adds j. Allocation requests $rc\,\mathrm{sizeof(int)}$ bytes. A non-null result must be initialized before its elements are read and released with free when no longer needed.

The pointer link always addresses the pointer that leads to the current node. On deletion, update that pointer and keep link in place so the next node is checked. On retention, advance to the next link. This covers head, consecutive and all-node matches, and releases each removed allocation. Time is $O(n)$; auxiliary space is $O(1)$. The following shared listing also contains the reversal for 9.

    #include <stdlib.h>
    typedef struct Node {
        int value;
        struct Node *next;
    } Node;
    void deleteAll(Node **head, int key) {
        if (!head) return;
        Node **link = head;
        while (*link) {
            if ((*link)->value == key) {
                Node *old = *link;
                *link = old->next;
                free(old);
            } else link = &(*link)->next;
        }
    }
    Node *reverse(Node *head) {
        Node *prev = NULL, *cur = head;
        while (cur) {
            Node *next = cur->next;
            cur->next = prev;
            prev = cur;
            cur = next;
        }
        return prev;
    }

Push each opening bracket. For a closing bracket, require a nonempty stack and matching opening type. Accept only if the stack is empty at the end. Time is $O(n)$; the fixed array uses capacity 100, as permitted by the question.

    int balanced(const char *s) {
        char stack[100];
        int top = 0;
        for (; *s; ++s) {
            if (*s == '(' || *s == '[') {
                if (top == 100) return 0;
                stack[top++] = *s;
            } else if (*s == ')' || *s == ']') {
                if (!top) return 0;
                char open = stack[--top];
                if ((*s == ')' && open != '(') ||
                    (*s == ']' && open != '[')) return 0;
            } else return 0;
        }
        return top == 0;
    }
